style.css:
@-moz-document domain("roblox.com") {
/* ===== Bloodlust Danganronpa Theme ===== */
body, html {
  background-color: #0b0b0b !important;
  color: #ff00bb !important;
  font-family: 'Segoe UI', 'Century Gothic', sans-serif !important;
}

/* Headings */
h1, h2, h3, h4 {
  color: #ffffff !important;
  text-shadow: 0 0 5px #ff00bb !important;
  border-bottom: 1px solid #ff00bb !important;
  font-family: 'Impact', 'Arial Black', sans-serif !important;
}

/* Text Elements */
a, p, span, div, label {
  color: #ff00bb !important;
}
a:hover {
  background-color: #ff00bb !important;
  color: #000 !important;
  padding: 2px 4px;
  border-radius: 2px;
}

/* Buttons */
button, input[type="submit"], .btn-primary, .btn-secondary {
  background-color: #ff00bb !important;
  color: #0b0b0b !important;
  border: none !important;
  border-radius: 4px !important;
  font-weight: bold;
  text-shadow: none !important;
}
button:hover, .btn-primary:hover, .btn-secondary:hover {
  background-color: #ff44cc !important;
  color: #000 !important;
}

/* Cards and Modules */
.card-item, .game-card-container {
  background-color: #141414 !important;
  border: 1px solid #ff00bb !important;
  box-shadow: 0 0 10px #ff00bb55;
}

/* Scrollbars */
::-webkit-scrollbar {
  width: 10px;
}
::-webkit-scrollbar-track {
  background: #0b0b0b;
}
::-webkit-scrollbar-thumb {
  background: #ff00bb;
  border-radius: 10px;
}

/* Selection Highlight */
::selection {
  background: #ff00bb;
  color: black;
}

/* Optional: blood-text effect class you can add manually in dev tools */
.blood-text {
  font-size: 2em;
  color: #ff00bb;
  text-shadow: 0 0 10px #ff00bb, 0 0 20px #ff00bb;
  font-weight: bold;
  letter-spacing: 2px;
  text-transform: uppercase;
}
}
